const listServerlessEndpointsUpdatedSince = `-- name: ListServerlessEndpointsUpdatedSince :many
SELECT id, tenant_id, name, namespace, kind, healthcheck_url, trigger_url, signing_secret_enc, request_timeout_seconds, poll_interval_seconds, inline_wait_budget_ms, labels, enabled, shard, healthy, status_error, status_changed_at, registered_actions, created_at, updated_at
FROM v1_serverless_endpoint
WHERE
    tenant_id = $1::UUID
    AND (GREATEST(updated_at, COALESCE(status_changed_at, updated_at)), id) > ($2::TIMESTAMPTZ, $3::UUID)
ORDER BY GREATEST(updated_at, COALESCE(status_changed_at, updated_at)), id
`

type ListServerlessEndpointsUpdatedSinceParams struct {
	Tenantid uuid.UUID          `json:"tenantid"`
	Since    pgtype.Timestamptz `json:"since"`
	Sinceid  uuid.UUID          `json:"sinceid"`
}

// Incremental refresh of a tenant's routing cache through v1_serverless_endpoint_version_idx.
// A row's version is the later of updated_at (configuration and registered_actions writes)
// and status_changed_at (health transitions written by the owner), so every write the cache
// needs to see surfaces here. Keyset on (version, id) from the last row the caller applied.
func (q *Queries) ListServerlessEndpointsUpdatedSince(ctx context.Context, db DBTX, arg ListServerlessEndpointsUpdatedSinceParams) ([]*V1ServerlessEndpoint, error) {
	rows, err := db.Query(ctx, listServerlessEndpointsUpdatedSince, arg.Tenantid, arg.Since, arg.Sinceid)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*V1ServerlessEndpoint
	for rows.Next() {
		var i V1ServerlessEndpoint
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Name,
			&i.Namespace,
			&i.Kind,
			&i.HealthcheckUrl,
			&i.TriggerUrl,
			&i.SigningSecretEnc,
			&i.RequestTimeoutSeconds,
			&i.PollIntervalSeconds,
			&i.InlineWaitBudgetMs,
			&i.Labels,
			&i.Enabled,
			&i.Shard,
			&i.Healthy,
			&i.StatusError,
			&i.StatusChangedAt,
			&i.RegisteredActions,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listServerlessProcesses = `-- name: ListServerlessProcesses :many
SELECT
    p.process_id, p.expires_at, p.unit_count, p.endpoint_count, p.hostname, p.version, p.started_at,
    (p.expires_at < now())::BOOLEAN AS expired
FROM v1_serverless_process p
ORDER BY p.process_id
`

type ListServerlessProcessesRow struct {
	V1ServerlessProcess V1ServerlessProcess `json:"v1_serverless_process"`
	Expired             bool                `json:"expired"`
}

// All process rows with liveness resolved in SQL, again so clock skew between processes does
// not matter. Callers split the result into live processes and dead process ids.
func (q *Queries) ListServerlessProcesses(ctx context.Context, db DBTX) ([]*ListServerlessProcessesRow, error) {
	rows, err := db.Query(ctx, listServerlessProcesses)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ListServerlessProcessesRow
	for rows.Next() {
		var i ListServerlessProcessesRow
		if err := rows.Scan(
			&i.V1ServerlessProcess.ProcessID,
			&i.V1ServerlessProcess.ExpiresAt,
			&i.V1ServerlessProcess.UnitCount,
			&i.V1ServerlessProcess.EndpointCount,
			&i.V1ServerlessProcess.Hostname,
			&i.V1ServerlessProcess.Version,
			&i.V1ServerlessProcess.StartedAt,
			&i.Expired,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const releaseAllServerlessLeases = `-- name: ReleaseAllServerlessLeases :execrows
UPDATE v1_serverless_lease
SET process_id = NULL, claimed_at = NULL
WHERE process_id = $1::UUID
`

func (q *Queries) ReleaseAllServerlessLeases(ctx context.Context, db DBTX, processid uuid.UUID) (int64, error) {
	result, err := db.Exec(ctx, releaseAllServerlessLeases, processid)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const shedServerlessLeases = `-- name: ShedServerlessLeases :many
UPDATE v1_serverless_lease l
SET process_id = NULL, claimed_at = NULL
FROM (
    SELECT
        unnest($2::UUID[]) AS tenant_id,
        unnest($3::INT[]) AS shard
) AS u
WHERE
    l.tenant_id = u.tenant_id
    AND l.shard = u.shard
    AND l.process_id = $1::UUID
RETURNING l.tenant_id, l.shard, l.endpoint_count
`

type ShedServerlessLeasesParams struct {
	Processid uuid.UUID   `json:"processid"`
	Tenantids []uuid.UUID `json:"tenantids"`
	Shards    []int32     `json:"shards"`
}

type ShedServerlessLeasesRow struct {
	TenantID      uuid.UUID `json:"tenant_id"`
	Shard         int32     `json:"shard"`
	EndpointCount int32     `json:"endpoint_count"`
}

// Releases the given units. Guarded by process_id so a process that lost a unit to a takeover
// (after being declared dead) cannot release the new owner's lease.
func (q *Queries) ShedServerlessLeases(ctx context.Context, db DBTX, arg ShedServerlessLeasesParams) ([]*ShedServerlessLeasesRow, error) {
	rows, err := db.Query(ctx, shedServerlessLeases, arg.Processid, arg.Tenantids, arg.Shards)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*ShedServerlessLeasesRow
	for rows.Next() {
		var i ShedServerlessLeasesRow
		if err := rows.Scan(&i.TenantID, &i.Shard, &i.EndpointCount); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateServerlessEndpoint = `-- name: UpdateServerlessEndpoint :one
UPDATE v1_serverless_endpoint
SET
    name = COALESCE($1::TEXT, name),
    kind = COALESCE($2::v1_serverless_endpoint_kind, kind),
    healthcheck_url = COALESCE($3::TEXT, healthcheck_url),
    trigger_url = COALESCE($4::TEXT, trigger_url),
    signing_secret_enc = COALESCE($5::TEXT, signing_secret_enc),
    request_timeout_seconds = COALESCE($6::INT, request_timeout_seconds),
    poll_interval_seconds = COALESCE($7::INT, poll_interval_seconds),
    inline_wait_budget_ms = COALESCE($8::INT, inline_wait_budget_ms),
    labels = COALESCE($9::JSONB, labels),
    enabled = COALESCE($10::BOOLEAN, enabled),
    updated_at = NOW()
WHERE
    tenant_id = $11::UUID
    AND id = $12::UUID
RETURNING id, tenant_id, name, namespace, kind, healthcheck_url, trigger_url, signing_secret_enc, request_timeout_seconds, poll_interval_seconds, inline_wait_budget_ms, labels, enabled, shard, healthy, status_error, status_changed_at, registered_actions, created_at, updated_at
`

type UpdateServerlessEndpointParams struct {
	Name                  pgtype.Text                  `json:"name"`
	Kind                  NullV1ServerlessEndpointKind `json:"kind"`
	HealthcheckUrl        pgtype.Text                  `json:"healthcheckUrl"`
	TriggerUrl            pgtype.Text                  `json:"triggerUrl"`
	SigningSecretEnc      pgtype.Text                  `json:"signingSecretEnc"`
	RequestTimeoutSeconds pgtype.Int4                  `json:"requestTimeoutSeconds"`
	PollIntervalSeconds   pgtype.Int4                  `json:"pollIntervalSeconds"`
	InlineWaitBudgetMs    pgtype.Int4                  `json:"inlineWaitBudgetMs"`
	Labels                []byte                       `json:"labels"`
	Enabled               pgtype.Bool                  `json:"enabled"`
	Tenantid              uuid.UUID                    `json:"tenantid"`
	ID                    uuid.UUID                    `json:"id"`
}

// namespace and shard are never updatable: the namespace prefixes everything the endpoint has
// registered with the engine, and the shard decides which lease unit owns the endpoint.
func (q *Queries) UpdateServerlessEndpoint(ctx context.Context, db DBTX, arg UpdateServerlessEndpointParams) (*V1ServerlessEndpoint, error) {
	row := db.QueryRow(ctx, updateServerlessEndpoint,
		arg.Name,
		arg.Kind,
		arg.HealthcheckUrl,
		arg.TriggerUrl,
		arg.SigningSecretEnc,
		arg.RequestTimeoutSeconds,
		arg.PollIntervalSeconds,
		arg.InlineWaitBudgetMs,
		arg.Labels,
		arg.Enabled,
		arg.Tenantid,
		arg.ID,
	)
	var i V1ServerlessEndpoint
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.Name,
		&i.Namespace,
		&i.Kind,
		&i.HealthcheckUrl,
		&i.TriggerUrl,
		&i.SigningSecretEnc,
		&i.RequestTimeoutSeconds,
		&i.PollIntervalSeconds,
		&i.InlineWaitBudgetMs,
		&i.Labels,
		&i.Enabled,
		&i.Shard,
		&i.Healthy,
		&i.StatusError,
		&i.StatusChangedAt,
		&i.RegisteredActions,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return &i, err
}

const updateServerlessEndpointRegisteredActions = `-- name: UpdateServerlessEndpointRegisteredActions :exec
UPDATE v1_serverless_endpoint
SET
    registered_actions = $1::TEXT[],
    updated_at = NOW()
WHERE id = $2::UUID
`

type UpdateServerlessEndpointRegisteredActionsParams struct {
	Registeredactions []string  `json:"registeredactions"`
	ID                uuid.UUID `json:"id"`
}

// Written by the owner when a healthcheck changes the endpoint's workflows. Bumps updated_at so
// ListServerlessEndpointsUpdatedSince surfaces the new action set to every registration for
// the tenant.
func (q *Queries) UpdateServerlessEndpointRegisteredActions(ctx context.Context, db DBTX, arg UpdateServerlessEndpointRegisteredActionsParams) error {
	_, err := db.Exec(ctx, updateServerlessEndpointRegisteredActions, arg.Registeredactions, arg.ID)
	return err
}

const updateServerlessEndpointStatus = `-- name: UpdateServerlessEndpointStatus :one
UPDATE v1_serverless_endpoint
SET
    healthy = $1::BOOLEAN,
    status_error = $2::TEXT,
    status_changed_at = NOW()
WHERE id = $3::UUID
RETURNING status_changed_at
`

type UpdateServerlessEndpointStatusParams struct {
	Healthy     bool        `json:"healthy"`
	StatusError pgtype.Text `json:"statusError"`
	ID          uuid.UUID   `json:"id"`
}

// Written by the owner on a healthy/unhealthy transition only. Deliberately leaves updated_at
// alone: a health flip is not a routing change. The write's own timestamp is returned so the
// writer's cache can order it against rows read before or after it.
func (q *Queries) UpdateServerlessEndpointStatus(ctx context.Context, db DBTX, arg UpdateServerlessEndpointStatusParams) (pgtype.Timestamptz, error) {
	row := db.QueryRow(ctx, updateServerlessEndpointStatus, arg.Healthy, arg.StatusError, arg.ID)
	var status_changed_at pgtype.Timestamptz
	err := row.Scan(&status_changed_at)
	return status_changed_at, err
}

const updateServerlessTenantShardCount = `-- name: UpdateServerlessTenantShardCount :one
UPDATE v1_serverless_tenant
SET shard_count = $1::INT
WHERE tenant_id = $2::UUID
RETURNING tenant_id, shard_count
`

type UpdateServerlessTenantShardCountParams struct {
	Shardcount int32     `json:"shardcount"`
	Tenantid   uuid.UUID `json:"tenantid"`
}

func (q *Queries) UpdateServerlessTenantShardCount(ctx context.Context, db DBTX, arg UpdateServerlessTenantShardCountParams) (*V1ServerlessTenant, error) {
	row := db.QueryRow(ctx, updateServerlessTenantShardCount, arg.Shardcount, arg.Tenantid)
	var i V1ServerlessTenant
	err := row.Scan(&i.TenantID, &i.ShardCount)
	return &i, err
}

const upsertServerlessProcess = `-- name: UpsertServerlessProcess :exec
INSERT INTO v1_serverless_process (process_id, expires_at, unit_count, endpoint_count, hostname, version)
VALUES (
    $1::UUID,
    now() + $2::interval,
    $3::INT,
    $4::INT,
    $5::TEXT,
    $6::TEXT
)
ON CONFLICT (process_id) DO UPDATE SET
    expires_at = EXCLUDED.expires_at,
    unit_count = EXCLUDED.unit_count,
    endpoint_count = EXCLUDED.endpoint_count
`

type UpsertServerlessProcessParams struct {
	Processid     uuid.UUID       `json:"processid"`
	Ttl           pgtype.Interval `json:"ttl"`
	Unitcount     int32           `json:"unitcount"`
	Endpointcount int32           `json:"endpointcount"`
	Hostname      pgtype.Text     `json:"hostname"`
	Version       pgtype.Text     `json:"version"`
}

// The process heartbeat. expires_at is computed in SQL so process clock skew does not matter.
func (q *Queries) UpsertServerlessProcess(ctx context.Context, db DBTX, arg UpsertServerlessProcessParams) error {
	_, err := db.Exec(ctx, upsertServerlessProcess,
		arg.Processid,
		arg.Ttl,
		arg.Unitcount,
		arg.Endpointcount,
		arg.Hostname,
		arg.Version,
	)
	return err
}

const upsertServerlessTenant = `-- name: UpsertServerlessTenant :one
INSERT INTO v1_serverless_tenant (tenant_id)
VALUES ($1::UUID)
ON CONFLICT (tenant_id) DO UPDATE
SET tenant_id = EXCLUDED.tenant_id
RETURNING tenant_id, shard_count
`

// Creates the tenant's serverless settings row with defaults if it does not exist and returns
// the current row either way. The no-op update makes RETURNING work on conflict.
func (q *Queries) UpsertServerlessTenant(ctx context.Context, db DBTX, tenantid uuid.UUID) (*V1ServerlessTenant, error) {
	row := db.QueryRow(ctx, upsertServerlessTenant, tenantid)
	var i V1ServerlessTenant
	err := row.Scan(&i.TenantID, &i.ShardCount)
	return &i, err
}
